// === Tab: mySketch ===
				// Sentences from Sol LeWitt
        // by Henrique Silva, 2025-09-28
        // https://openprocessing.org/sketch/2742098
        // #p5js #generativeart #creativecoding

        'use strict';
        let font;
        let pg

        let sentences = [{ t: "Banal ideas cannot be rescued by beautiful execution", l: 4 }, { t: "It is difficult to bungle a good idea.", l: 3 },
        { t: "Irrational judgements lead to new experience", l: 3 }, { t: "Irrational thoughts should be followed absolutely and logically.", l: 4 },
        { t: "The conventions of art are altered by works of art", l: 3 }]

        function preload() {
            font = loadFont('https://openprocessing.org/sketch/2742098/files/FreeSans.otf');
        }

        let font_size = 24
        let sn
        let pos = []
        let palette = ["#2c695a", "#4ad6af", "#7facc6", "#4e93cc", "#f6684f", "#ffd300"];


        function setup() {
            createCanvas(600, 750, WEBGL);
            stroke(0)
            background(0);


					frameRate(30)

        }

        function draw() {
            let pgx = 200
            let pgy = 140
            sn = floor(random(sentences.length))

            if (sentences[sn].l == 4) pgy = 200
            else if (sentences[sn].l == 5) pgy = 260

            pg = createGraphics(pgx, pgy);
            pg.pixelDensity(1); // Make sure pixels match
            pg.background("#ff");
            pg.fill("#000000")
            pg.textSize(font_size);

            pg.text(sentences[sn].t, 20, font_size / 2, pgx - 20)

            drawStrip(drawGaussianParallelogram()); 

            if (frameCount % 100 == 0) background(0);


        }

        function drawGaussianParallelogram() {
            let pts = []
            // Base parameters
            let cx = randomGaussian() * 300; // position around center
            let cy = randomGaussian() * 300;

            let w = 150 + randomGaussian() * 10;  // width
            let h = 90 + randomGaussian() * 6;   // height
            let skew = randomGaussian() * 30;    // skew factor (controls parallelogram slant)
            let angle = randomGaussian() * TAU;  // slight rotation

            pts.push(createVector(cx - w / 2, cy - h / 2));
            pts.push(createVector(cx + w / 2, cy - h / 2));
            pts.push(createVector(cx + w / 2 + skew, cy + h / 2));
            pts.push(createVector(cx - w / 2 + skew, cy + h / 2));

            return rotatePointsAroundCenter(pts, angle)

        }

        function rotatePointsAroundCenter(pts, angle) {
            // mass center
            var cx = 0, cy = 0;
            for (let p of pts) {
                cx += p.x;
                cy += p.y;
            }
            cx /= pts.length;
            cy /= pts.length;

            // Points rotation
            return pts.map(p => {
                let dx = p.x - cx;
                let dy = p.y - cy;
                let x = dx * cos(angle) - dy * sin(angle) + cx;
                let y = dx * sin(angle) + dy * cos(angle) + cy;
                return createVector(x, y);
            });
        }

        function drawStrip(basePoints) {

            noStroke()

            texture(pg)
            textureMode(NORMAL);

            beginShape(TRIANGLE_STRIP);

            vertex(basePoints[0].x, basePoints[0].y, 0, 0, 0);
            vertex(basePoints[3].x, basePoints[3].y, 0, 0, 1);
            vertex(basePoints[1].x, basePoints[1].y, 0, 1, 0);
            vertex(basePoints[2].x, basePoints[2].y, 0, 1, 1);
            vertex(basePoints[3].x, basePoints[3].y, 0, 0, 1);
            vertex(basePoints[1].x, basePoints[1].y, 0, 1, 0);

            endShape(CLOSE)

            stroke(0)
            noFill()

            beginShape()
            basePoints.forEach((element, index) => {
                vertex(element.x, element.y)
            });
            endShape(CLOSE)

        }
